window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-505f32196de01614"]={"versions": [{"id": "FIG-505f32196de01614", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR ECU-Konfigurationsmetamodells (ECUC Parameter Definition) für den Crypto Service Manager (CSM). Dargestellt ist die Struktur des Konfigurationscontainers <code>CsmGeneral</code> innerhalb des BSW-Moduls CSM auf System-/Modulkonfigurationsebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist ein Hauptcontainer sowie drei zugeordnete Konfigurationsparameter über Kompositionen mit der Rollenbezeichnung <code>+parameter</code>:</p>\n<ul class=\"fig-list\">\n<li><code>CsmGeneral: EcucParamConfContainerDef</code>: Konfigurationscontainer für allgemeine CSM-Einstellungen.</li>\n<li><code>CsmDevErrorDetect: EcucBooleanParamDef</code>: Boolescher Konfigurationsparameter mit dem Attribut <code>defaultValue = false</code>.</li>\n<li><code>CsmVersionInfoApi: EcucBooleanParamDef</code>: Boolescher Konfigurationsparameter mit dem Attribut <code>defaultValue = false</code>.</li>\n<li><code>CsmMainFunctionPeriod: EcucFloatParamDef</code>: Fließkommaparameter mit den Wertebereichs- und Multiplizitätsattributen <code>min = 0</code>, <code>max = INF</code>, <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Interaktionen oder Laufzeitsequenzen. Die Parameter steuern die Codegenerierung bzw. das Laufzeitverhalten des CSM: <code>CsmDevErrorDetect</code> aktiviert/deaktiviert die Erkennung von Entwicklungsfehlern, <code>CsmVersionInfoApi</code> schaltet die Schnittstelle zur Abfrage von Versionsinformationen frei und <code>CsmMainFunctionPeriod</code> definiert die Zykluszeit für die zyklische CSM-Hauptfunktion <code>Csm_MainFunction</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsspezifikation gemäß AUTOSAR ECUC:</p>\n<ul class=\"fig-list\">\n<li><code>CsmDevErrorDetect</code> und <code>CsmVersionInfoApi</code> sind standardmäßig deaktiviert (<code>defaultValue = false</code>).</li>\n<li><code>CsmMainFunctionPeriod</code> ist ein optionaler Parameter (Multiplizität 0..1) mit nicht-negativem Wertebereich (<code>min = 0</code>, <code>max = INF</code>). Bei Vorhandensein dient er BSW-Planungswerkzeugen zur Konfiguration des zyklischen Aufrufs der Hauptfunktion. Implementierer müssen die Codegeneratoren und Modultreiber entsprechend diesen Parametervorgaben auslegen.</li>\n</ul>"}, {"id": "FIG-6d65b68d89630363", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR ECU-Konfigurationsmetamodells (ECUC Parameter Definition) für den Crypto Service Manager (CSM). Dargestellt ist die Struktur des Konfigurationscontainers <code>CsmGeneral</code> innerhalb des BSW-Moduls CSM auf System-/Modulkonfigurationsebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist ein Hauptcontainer sowie zwei zugeordnete Konfigurationsparameter über Kompositionen mit der Rollenbezeichnung <code>+parameter</code>:</p>\n<ul class=\"fig-list\">\n<li><code>CsmGeneral: EcucParamConfContainerDef</code>: Konfigurationscontainer für allgemeine CSM-Einstellungen.</li>\n<li><code>CsmDevErrorDetect: EcucBooleanParamDef</code>: Boolescher Konfigurationsparameter mit dem Attribut <code>defaultValue = false</code>.</li>\n<li><code>CsmVersionInfoApi: EcucBooleanParamDef</code>: Boolescher Konfigurationsparameter mit dem Attribut <code>defaultValue = false</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Interaktionen oder Laufzeitsequenzen. Die Parameter steuern statisch die Modulkonfiguration: <code>CsmDevErrorDetect</code> schaltet die Erkennung und Meldung von Entwicklungsfehlern ein oder aus, <code>CsmVersionInfoApi</code> steuert das Vorhandensein der API-Funktion zur Abfrage der Versionsinformationen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsspezifikation gemäß AUTOSAR ECUC:</p>\n<ul class=\"fig-list\">\n<li><code>CsmDevErrorDetect</code> und <code>CsmVersionInfoApi</code> sind standardmäßig deaktiviert (<code>defaultValue = false</code>).</li>\n<li>Das Schema des Containers <code>CsmGeneral</code> umfasst ausschließlich diese beiden booleschen Parameter. Implementierer und Konfigurationswerkzeuge dürfen innerhalb dieses Containers keine weiteren allgemeinen Periodenparameter für die Hauptfunktion vorsehen.</li>\n</ul>"}], "trans": [{"from": "FIG-505f32196de01614", "to": "FIG-6d65b68d89630363", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Parameter <code>CsmMainFunctionPeriod</code> (<code>EcucFloatParamDef</code> mit <code>min = 0</code>, <code>max = INF</code>, <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>) über die Kompositionsbeziehung <code>+parameter</code> entfernt.</li>\n</ul>"}]};
